    GiamsatEntitiesTableWidgetComponent.prototype.handleCycleTimeHoanThanh = function (entity_dashDauRa, entity_STATUS, entity_startTime, entity_runningTime) {
        var num = parseFloat(entity_dashDauRa) / parseFloat(this.handleRunningTime(entity_STATUS, entity_startTime, entity_runningTime));
        // console.log("--------- PHD CycleTimeHoanThanh ----------------", Math.round(num * 1000000) / 1000000);
        var cycle_TimeHoanThanh = Math.round(num * 1000000) / 1000000;
        return cycle_TimeHoanThanh.toString() == 'NaN' ? '' : cycle_TimeHoanThanh;
    };
    GiamsatEntitiesTableWidgetComponent.prototype.handleRunningTime = function (entity_STATUS, entity_startTime, entity_runningTime) {
        var countRunning = entity_runningTime;
        var STATUS = parseInt(entity_STATUS);
        switch (STATUS) {
            case 1:
                countRunning = Math.floor((Date.now() - parseInt(entity_startTime) + parseInt(entity_runningTime)) /
                    1000);
                break;
            case 0:
                countRunning = parseInt(entity_runningTime) / 1000;
                break;
            case 3:
                countRunning = parseInt(entity_runningTime) / 1000;
                break;
        }
        return countRunning;
    };
