function isPublicDashboard(dashboard) {
    if (dashboard && dashboard.assignedCustomers) {
        return dashboard.assignedCustomers
            .filter(function (customerInfo) { return customerInfo.public; }).length > 0;
    }
    else {
        return false;
    }
}
function getDashboardAssignedCustomersText(dashboard) {
    if (dashboard && dashboard.assignedCustomers && dashboard.assignedCustomers.length > 0) {
        return dashboard.assignedCustomers
            .filter(function (customerInfo) { return !customerInfo.public; })
            .map(function (customerInfo) { return customerInfo.title; })
            .join(', ');
    }
    else {
        return '';
    }
}
function isCurrentPublicDashboardCustomer(dashboard, customerId) {
    if (customerId && dashboard && dashboard.assignedCustomers) {
        return dashboard.assignedCustomers.filter(function (customerInfo) {
            return customerInfo.public && customerId === customerInfo.customerId.id;
        }).length > 0;
    }
    else {
        return false;
    }
}


