  f = f.replace(/COM\.MICROSOFT\./g, "");
  /* Part 3 Section 5.8 References */

  f = f.replace(/\[((?:\.[A-Z]+[0-9]+)(?::\.[A-Z]+[0-9]+)?)\]/g, function ($$, $1) {
    return $1.replace(/\./g, "");
  });
