var PSCLSID = {
  SI: "e0859ff2f94f6810ab9108002b27b3d9",
  DSI: "02d5cdd59c2e1b10939708002b2cf9ae",
  UDI: "05d5cdd59c2e1b10939708002b2cf9ae"
};

function parse_xls_props(cfb
/*:CFBContainer*/
, props, o) {
  /* [MS-OSHARED] 2.3.3.2.2 Document Summary Information Property Set */
  var DSI = CFB.find(cfb, '/!DocumentSummaryInformation');
  if (DSI && DSI.size > 0) try {
    var DocSummary = parse_PropertySetStream(DSI, DocSummaryPIDDSI, PSCLSID.DSI);

    for (var d in DocSummary) {
      props[d] = DocSummary[d];
    }
  } catch (e) {
    if (o.WTF) throw e;
    /* empty */
  }
  /* [MS-OSHARED] 2.3.3.2.1 Summary Information Property Set*/

  var SI = CFB.find(cfb, '/!SummaryInformation');
  if (SI && SI.size > 0) try {
    var Summary = parse_PropertySetStream(SI, SummaryPIDSI, PSCLSID.SI);

    for (var s in Summary) {
      if (props[s] == null) props[s] = Summary[s];
    }
  } catch (e) {
    if (o.WTF) throw e;
    /* empty */
  }

  if (props.HeadingPairs && props.TitlesOfParts) {
    load_props_pairs(props.HeadingPairs, props.TitlesOfParts, props, o);
    delete props.HeadingPairs;
    delete props.TitlesOfParts;
  }
}

function write_xls_props(wb
/*:Workbook*/
, cfb
/*:CFBContainer*/
) {
  var DSEntries = [],
      SEntries = [],
      CEntries = [];
  var i = 0,
      Keys;
  var DocSummaryRE
  /*:{[key:string]:string}*/
  = evert_key(DocSummaryPIDDSI, "n");
  var SummaryRE
  /*:{[key:string]:string}*/
  = evert_key(SummaryPIDSI, "n");

  if (wb.Props) {
    Keys = keys(wb.Props); // $FlowIgnore

    for (i = 0; i < Keys.length; ++i) {
      (Object.prototype.hasOwnProperty.call(DocSummaryRE, Keys[i]) ? DSEntries : Object.prototype.hasOwnProperty.call(SummaryRE, Keys[i]) ? SEntries : CEntries).push([Keys[i], wb.Props[Keys[i]]]);
    }
  }

  if (wb.Custprops) {
    Keys = keys(wb.Custprops); // $FlowIgnore

    for (i = 0; i < Keys.length; ++i) {
      if (!Object.prototype.hasOwnProperty.call(wb.Props || {}, Keys[i])) (Object.prototype.hasOwnProperty.call(DocSummaryRE, Keys[i]) ? DSEntries : Object.prototype.hasOwnProperty.call(SummaryRE, Keys[i]) ? SEntries : CEntries).push([Keys[i], wb.Custprops[Keys[i]]]);
    }
  }

  var CEntries2 = [];

  for (i = 0; i < CEntries.length; ++i) {
    if (XLSPSSkip.indexOf(CEntries[i][0]) > -1 || PseudoPropsPairs.indexOf(CEntries[i][0]) > -1) continue;
    if (CEntries[i][1] == null) continue;
    CEntries2.push(CEntries[i]);
  }

  if (SEntries.length) CFB.utils.cfb_add(cfb, "/\x05SummaryInformation", write_PropertySetStream(SEntries, PSCLSID.SI, SummaryRE, SummaryPIDSI));
  if (DSEntries.length || CEntries2.length) CFB.utils.cfb_add(cfb, "/\x05DocumentSummaryInformation", write_PropertySetStream(DSEntries, PSCLSID.DSI, DocSummaryRE, DocSummaryPIDDSI, CEntries2.length ? CEntries2 : null, PSCLSID.UDI));
}

